mapper.select:
select A.BATCH_ID AS batchId, C.TASK_ID as taskId, C.TASK_NAME as taskName, A.TASK_STATUS as taskStatus, A.START_TIME as startTime, A.END_TIME as endTime, A.START_DATE as busiStart, A.END_DATE as busiEnd, A.TASK_RESULT as taskResult, IFNULL(B.REAL_NAME, 'system') as taskAssign, A.START_MODULE as startModule, A.GRADE_TYPE as taskPriority, A.TASK_CREATE_TIME as createTime from CHB_SYS_BATCH_LOG A LEFT JOIN CHB_SYS_USER B ON B.USER_ID = A.TASK_ASSIGN AND B.STATUS = 'E' LEFT JOIN CHB_SYS_TASK C ON A.TASK_ID = C.TASK_ID
AND A.TASK_ID = #{taskId,jdbcType=VARCHAR}
AND A.TASK_RESULT = #{taskResult,jdbcType=VARCHAR}
AND A.START_DATE >= STR_TO_DATE(#{busiDateStart}, '%Y-%m-%d')
AND A.END_DATE <= STR_TO_DATE(#{busiDateEnd}, '%Y-%m-%d')
#{item}
ORDER BY A.CREATE_TIME DESC
